from __future__ import annotations

import sys
from collections import Counter

HELP = (
    "Usage: textstats [--top N]  # read stdin, print word and line counts; "
10→    "with --top N also print the N most frequent words\n"
)


def count_words(text: str) -> int:
    return len(text.split())


def count_lines(text: str) -> int:
    if text == "":
20→        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)


def is_top_count(token: str) -> bool:
    # N is an unsigned decimal with no leading zero: [1-9][0-9]*.
    if not token or token[0] not in "123456789":
        return False
    return all(ch in "0123456789" for ch in token[1:])

30→
def ranking(text: str, limit: int) -> list[tuple[str, int]]:
    counts = Counter(text.split())
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["--help"]:
40→        sys.stdout.write(HELP)
        return 0
    top: int | None
    if not args:
        top = None
    elif len(args) == 2 and args[0] == "--top" and is_top_count(args[1]):
        top = int(args[1])
    else:
        sys.stderr.write(HELP)
        return 2
50→    data = sys.stdin.read()
    sys.stdout.write(f"words: {count_words(data)}\nlines: {count_lines(data)}\n")
    if top is not None:
        for word, freq in ranking(data, top):
            sys.stdout.write(f"{word} {freq}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
